begin;
create table public.health_items (
 user_id uuid not null references auth.users(id) on delete cascade,
 id text not null default gen_random_uuid()::text check (length(id) between 1 and 80),
 kind text not null check (kind in ('category','habit','navigation')),
 name text not null check (length(trim(name)) between 1 and 100),
 icon text not null check (length(icon) between 1 and 32),
 metric text not null default 'count' check (metric in ('count','quantity','minutes','sleep')),
 unit text not null default '' check (length(unit)<=20),
 target numeric not null default 0 check (target between 0 and 1000000),
 overview boolean not null default false, quick boolean not null default false,
 quick_amount numeric not null default 0 check (quick_amount between 0 and 100000),
 position integer not null default 0 check (position between 0 and 100000),
 archived boolean not null default false,
 route text not null default 'today' check (route in ('today','journal','habits','week')),
 primary key (user_id,id)
);
alter table public.health_items enable row level security;
create policy "health_items_own_rows" on public.health_items for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
revoke all on public.health_items from anon;
grant select,insert,update,delete on public.health_items to authenticated;

insert into public.health_items(user_id,id, kind, name, icon, metric, unit, target, overview, quick, quick_amount, position, archived, route) select users.id,seed.* from auth.users as users cross join jsonb_to_recordset('[{"id":"sleep","kind":"category","name":"Giấc ngủ","icon":"moon","metric":"sleep","unit":"phút","target":480,"overview":true,"quick":true,"quick_amount":0,"position":0,"archived":false,"route":"today"},{"id":"fitness","kind":"category","name":"Vận động","icon":"dumbbell","metric":"minutes","unit":"cái","target":45,"overview":true,"quick":true,"quick_amount":0,"position":1,"archived":false,"route":"today"},{"id":"food","kind":"category","name":"Ăn uống","icon":"utensils","metric":"count","unit":"bữa","target":3,"overview":true,"quick":true,"quick_amount":0,"position":2,"archived":false,"route":"today"},{"id":"water","kind":"category","name":"Uống nước","icon":"droplet","metric":"quantity","unit":"ml","target":2000,"overview":true,"quick":true,"quick_amount":200,"position":3,"archived":false,"route":"today"},{"id":"study","kind":"category","name":"Học & làm","icon":"book-open","metric":"minutes","unit":"phút","target":0,"overview":false,"quick":true,"quick_amount":0,"position":4,"archived":false,"route":"today"},{"id":"rest","kind":"category","name":"Nghỉ ngơi / đi chơi","icon":"coffee","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":5,"archived":false,"route":"today"},{"id":"move","kind":"habit","name":"Vận động ít nhất 30 phút","icon":"dumbbell","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":0,"archived":false,"route":"today"},{"id":"breakfast","kind":"habit","name":"Ăn sáng trước 8 giờ","icon":"utensils","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":1,"archived":false,"route":"today"},{"id":"read","kind":"habit","name":"Đọc sách 15 phút","icon":"book-open","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":2,"archived":false,"route":"today"},{"id":"sleep-habit","kind":"habit","name":"Đi ngủ trước 23 giờ","icon":"moon","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":3,"archived":false,"route":"today"},{"id":"nav-today","kind":"navigation","name":"Hôm nay","icon":"layout-dashboard","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":0,"archived":false,"route":"today"},{"id":"nav-journal","kind":"navigation","name":"Nhật ký","icon":"notebook-pen","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":1,"archived":false,"route":"journal"},{"id":"nav-habits","kind":"navigation","name":"Thói quen","icon":"list-checks","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":2,"archived":false,"route":"habits"},{"id":"nav-week","kind":"navigation","name":"Tổng quan tuần","icon":"chart-column","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":3,"archived":false,"route":"week"}]'::jsonb) as seed(id text,kind text,name text,icon text,metric text,unit text,target numeric,overview boolean,quick boolean,quick_amount numeric,position integer,archived boolean,route text);
create function public.health_seed_items() returns void language sql security invoker set search_path='' as $function$
 insert into public.health_items(user_id,id, kind, name, icon, metric, unit, target, overview, quick, quick_amount, position, archived, route) select auth.uid(),seed.* from jsonb_to_recordset('[{"id":"sleep","kind":"category","name":"Giấc ngủ","icon":"moon","metric":"sleep","unit":"phút","target":480,"overview":true,"quick":true,"quick_amount":0,"position":0,"archived":false,"route":"today"},{"id":"fitness","kind":"category","name":"Vận động","icon":"dumbbell","metric":"minutes","unit":"cái","target":45,"overview":true,"quick":true,"quick_amount":0,"position":1,"archived":false,"route":"today"},{"id":"food","kind":"category","name":"Ăn uống","icon":"utensils","metric":"count","unit":"bữa","target":3,"overview":true,"quick":true,"quick_amount":0,"position":2,"archived":false,"route":"today"},{"id":"water","kind":"category","name":"Uống nước","icon":"droplet","metric":"quantity","unit":"ml","target":2000,"overview":true,"quick":true,"quick_amount":200,"position":3,"archived":false,"route":"today"},{"id":"study","kind":"category","name":"Học & làm","icon":"book-open","metric":"minutes","unit":"phút","target":0,"overview":false,"quick":true,"quick_amount":0,"position":4,"archived":false,"route":"today"},{"id":"rest","kind":"category","name":"Nghỉ ngơi / đi chơi","icon":"coffee","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":5,"archived":false,"route":"today"},{"id":"move","kind":"habit","name":"Vận động ít nhất 30 phút","icon":"dumbbell","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":0,"archived":false,"route":"today"},{"id":"breakfast","kind":"habit","name":"Ăn sáng trước 8 giờ","icon":"utensils","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":1,"archived":false,"route":"today"},{"id":"read","kind":"habit","name":"Đọc sách 15 phút","icon":"book-open","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":2,"archived":false,"route":"today"},{"id":"sleep-habit","kind":"habit","name":"Đi ngủ trước 23 giờ","icon":"moon","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":3,"archived":false,"route":"today"},{"id":"nav-today","kind":"navigation","name":"Hôm nay","icon":"layout-dashboard","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":0,"archived":false,"route":"today"},{"id":"nav-journal","kind":"navigation","name":"Nhật ký","icon":"notebook-pen","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":1,"archived":false,"route":"journal"},{"id":"nav-habits","kind":"navigation","name":"Thói quen","icon":"list-checks","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":2,"archived":false,"route":"habits"},{"id":"nav-week","kind":"navigation","name":"Tổng quan tuần","icon":"chart-column","metric":"count","unit":"lần","target":0,"overview":false,"quick":false,"quick_amount":0,"position":3,"archived":false,"route":"week"}]'::jsonb) as seed(id text,kind text,name text,icon text,metric text,unit text,target numeric,overview boolean,quick boolean,quick_amount numeric,position integer,archived boolean,route text) where auth.uid() is not null on conflict (user_id,id) do nothing;
$function$;
revoke all on function public.health_seed_items() from public,anon;
grant execute on function public.health_seed_items() to authenticated;

alter table public.health_activities drop constraint health_activities_category_check;
alter table public.health_activities add column icon text not null default '' check (length(icon)<=32);
alter table public.health_activities add constraint health_activities_item_fk foreign key(user_id,category) references public.health_items(user_id,id);
alter table public.health_habit_checks drop constraint health_habit_checks_habit_check;
update public.health_habit_checks set habit='sleep-habit' where habit='sleep';
alter table public.health_habit_checks add constraint health_habit_checks_item_fk foreign key(user_id,habit) references public.health_items(user_id,id);
commit;
